class Solution:
    def friendRequests(self, n: int, restrictions: list[list[int]], requests: list[list[int]]) -> list[bool]:
        parent = list(range(n))
        def find(x):
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x
        result = []
        for u, v in requests:
            pu, pv = find(u), find(v)
            if pu == pv:
                result.append(True)
                continue
            ok = True
            for a, b in restrictions:
                pa, pb = find(a), find(b)
                if (pa == pu and pb == pv) or (pa == pv and pb == pu):
                    ok = False
                    break
            if ok:
                parent[pu] = pv
            result.append(ok)
        return result

